class Solution:
    def solve(self, spec_path: str = None) -> dict:
        code = r'''
import networkx as nx
from collections import defaultdict
import random
import math

class BroadCastTopology:
    def __init__(self, src, dsts, num_partitions):
        self.src = src
        self.dsts = dsts
        self.num_partitions = int(num_partitions)
        self.paths = {dst: {str(i): None for i in range(self.num_partitions)} for dst in dsts}

    def append_dst_partition_path(self, dst, partition, path):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

    def set_dst_partition_paths(self, dst, partition, paths):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def set_num_partitions(self, num_partitions):
        self.num_partitions = num_partitions


def search_algorithm(src, dsts, G, num_partitions):
    num_vms = 1
    instance_rate = 0.54

    # Extract data_vol from graph if available
    data_vol = 300.0
    if hasattr(G, 'graph') and 'data_vol' in G.graph:
        data_vol = float(G.graph['data_vol'])

    partition_size = data_vol / num_partitions  # GB per partition

    ingress_limits = {"aws": 10, "gcp": 16, "azure": 16}
    egress_limits = {"aws": 5, "gcp": 7, "azure": 16}

    def get_provider(node):
        return node.split(":")[0]

    def node_egress_bw(node):
        return egress_limits.get(get_provider(node), 5) * num_vms

    def node_ingress_bw(node):
        return ingress_limits.get(get_provider(node), 10) * num_vms

    def make_edge_list(path):
        """Convert a node path to list of [u, v, edge_data] edges."""
        edges = []
        for i in range(len(path) - 1):
            u, v = path[i], path[i+1]
            if G.has_edge(u, v):
                edges.append([u, v, dict(G[u][v])])
            else:
                edges.append([u, v, {}])
        return edges

    # Generate candidate paths using multiple methods
    K_PATHS = 30
    dst_paths = {}

    for dst in dsts:
        paths = []
        seen = set()

        # Cost-based k-shortest
        try:
            gen = nx.shortest_simple_paths(G, src, dst, weight="cost")
            for i, p in enumerate(gen):
                if i >= K_PATHS:
                    break
                key = tuple(p)
                if key not in seen:
                    seen.add(key)
                    paths.append(p)
        except:
            pass

        # Hop-based shortest
        try:
            sp = nx.shortest_path(G, src, dst)
            key = tuple(sp)
            if key not in seen:
                seen.add(key)
                paths.append(sp)
        except:
            pass

        # Throughput-optimized path
        try:
            inv_G = nx.DiGraph()
            for u, v, d in G.edges(data=True):
                tp = d.get("throughput", 0.001)
                inv_G.add_edge(u, v, weight=1.0/max(tp, 0.001))
            tp_path = nx.shortest_path(inv_G, src, dst, weight="weight")
            key = tuple(tp_path)
            if key not in seen:
                seen.add(key)
                paths.append(tp_path)
        except:
            pass

        # Combined cost+throughput weight paths
        for alpha in [0.1, 0.3, 0.5, 0.7, 0.9]:
            try:
                combo_G = nx.DiGraph()
                max_cost = max((d.get("cost", 0.01) for _, _, d in G.edges(data=True)), default=0.01)
                max_inv_tp = max((1.0/max(d.get("throughput", 0.001), 0.001) for _, _, d in G.edges(data=True)), default=1.0)
                for u, v, d in G.edges(data=True):
                    c = d.get("cost", 0.01) / max(max_cost, 1e-10)
                    t = (1.0/max(d.get("throughput", 0.001), 0.001)) / max(max_inv_tp, 1e-10)
                    combo_G.add_edge(u, v, weight=alpha*c + (1-alpha)*t)
                cp = nx.shortest_path(combo_G, src, dst, weight="weight")
                key = tuple(cp)
                if key not in seen:
                    seen.add(key)
                    paths.append(cp)
            except:
                pass

        if not paths:
            # Last resort: any path
            try:
                sp = nx.shortest_path(G, src, dst)
                paths.append(sp)
            except:
                pass

        dst_paths[dst] = paths

    def compute_cost_for_plan(plan):
        """
        plan: dict of dst -> list of path_indices (one per partition)
        Returns estimated total cost.
        """
        # Build edge usage
        edge_parts = defaultdict(int)
        node_out_edges = defaultdict(set)
        node_in_edges = defaultdict(set)
        nodes_used = set()

        for dst in dsts:
            if dst not in plan:
                return float('inf')
            indices = plan[dst]
            paths = dst_paths.get(dst, [])
            if not paths:
                return float('inf')
            for pidx in indices:
                if pidx >= len(paths):
                    return float('inf')
                path = paths[pidx]
                for i in range(len(path)-1):
                    u, v = path[i], path[i+1]
                    edge_parts[(u,v)] += 1
                    node_out_edges[u].add((u,v))
                    node_in_edges[v].add((u,v))
                    nodes_used.add(u)
                    nodes_used.add(v)

        if not edge_parts:
            return float('inf')

        # Egress cost
        egress_cost = 0.0
        for (u,v), cnt in edge_parts.items():
            c = G[u][v].get("cost", 0.0)
            egress_cost += cnt * partition_size * c

        # Transfer time estimation
        # For each edge: effective bandwidth considering sharing
        max_time = 0.0
        for (u,v), cnt in edge_parts.items():
            edge_tp = G[u][v].get("throughput", 0.001)
            n_out = len(node_out_edges[u])
            n_in = len(node_in_edges[v])
            eg_share = node_egress_bw(u) / max(n_out, 1)
            ig_share = node_ingress_bw(v) / max(n_in, 1)
            actual_bw = min(edge_tp, eg_share, ig_share)
            if actual_bw <= 0:
                actual_bw = 0.001
            # Time for this edge to transfer all its partitions
            t = cnt * partition_size * 8.0 / actual_bw
            if t > max_time:
                max_time = t

        inst_cost = len(nodes_used) * num_vms * (instance_rate / 3600.0) * max_time
        return egress_cost + inst_cost

    def compute_cost_for_plan_v2(plan):
        """
        Alternative cost model: time = max over destinations of sum of hop times.
        Each hop's time = partition_size * 8 / min(edge_tp, shared_egress, shared_ingress)
        """
        edge_parts = defaultdict(int)
        node_out_edges = defaultdict(set)
        node_in_edges = defaultdict(set)
        nodes_used = set()
        dst_partition_paths = {}

        for dst in dsts:
            if dst not in plan:
                return float('inf')
            indices = plan[dst]
            paths = dst_paths.get(dst, [])
            if not paths:
                return float('inf')
            dst_partition_paths[dst] = []
            for pidx in indices:
                if pidx >= len(paths):
                    return float('inf')
                path = paths[pidx]
                dst_partition_paths[dst].append(path)
                for i in range(len(path)-1):
                    u, v = path[i], path[i+1]
                    edge_parts[(u,v)] += 1
                    node_out_edges[u].add((u,v))
                    node_in_edges[v].add((u,v))
                    nodes_used.add(u)
                    nodes_used.add(v)

        if not edge_parts:
            return float('inf')

        egress_cost = 0.0
        for (u,v), cnt in edge_parts.items():
            c = G[u][v].get("cost", 0.0)
            egress_cost += cnt * partition_size * c

        # Compute edge bandwidth
        edge_bw = {}
        for (u,v), cnt in edge_parts.items():
            edge_tp = G[u][v].get("throughput", 0.001)
            n_out = len(node_out_edges[u])
            n_in = len(node_in_edges[v])
            eg_share = node_egress_bw(u) / max(n_out, 1)
            ig_share = node_ingress_bw(v) / max(n_in, 1)
            actual_bw = min(edge_tp, eg_share, ig_share)
            if actual_bw <= 0:
                actual_bw = 0.001
            edge_bw[(u,v)] = actual_bw

        # Time: max over all edges of (cnt * partition_size * 8 / bw)
        max_time = 0.0
        for (u,v), cnt in edge_parts.items():
            t = cnt * partition_size * 8.0 / edge_bw[(u,v)]
            if t > max_time:
                max_time = t

        inst_cost = len(nodes_used) * num_vms * (instance_rate / 3600.0) * max_time
        return egress_cost + inst_cost

    # Try multiple num_vms values
    best_overall_cost = float('inf')
    best_overall_plan = None
    best_overall_vms = num_vms

    for try_vms in [1, 2]:
        num_vms = try_vms

        # Strategy 1: all same cheapest cost path per dst
        def strategy_cheapest():
            plan = {}
            for dst in dsts:
                paths = dst_paths.get(dst, [])
                if not paths:
                    return None
                best_idx = 0
                best_c = float('inf')
                for idx, p in enumerate(paths):
                    c = sum(G[p[i]][p[i+1]].get("cost", 0) for i in range(len(p)-1))
                    if c < best_c:
                        best_c = c
                        best_idx = idx
                plan[dst] = [best_idx] * num_partitions
            return plan

        # Strategy 2: per-dst independent best 
        def strategy_independent_best():
            plan = {}
            for dst in dsts:
                paths = dst_paths.get(dst, [])
                if not paths:
                    return None
                best_idx = 0
                best_c = float('inf')
                for idx, path in enumerate(paths):
                    edge_cost = 0.0
                    min_bw = float('inf')
                    n_nodes = len(set(path))
                    for i in range(len(path)-1):
                        u, v = path[i], path[i+1]
                        edge_cost += G[u][v].get("cost", 0) * partition_size * num_partitions
                        tp = G[u][v].get("throughput", 0.001)
                        eg = node_egress_bw(u)
                        ig = node_ingress_bw(v)
                        bw = min(tp, eg, ig)
                        if bw < min_bw:
                            min_bw = bw
                    if min_bw <= 0:
                        min_bw = 0.001
                    tt = num_partitions * partition_size * 8.0 / min_bw
                    ic = n_nodes * num_vms * (instance_rate / 3600.0) * tt
                    score = edge_cost + ic
                    if score < best_c:
                        best_c = score
                        best_idx = idx
                plan[dst] = [best_idx] * num_partitions
            return plan

        # Strategy 3: greedy destination-by-destination
        def strategy_greedy():
            plan = {}
            accumulated_edges = defaultdict(int)
            accumulated_out = defaultdict(set)
            accumulated_in = defaultdict(set)
            accumulated_nodes = set()

            # Sort destinations by number of candidate paths (fewest first)
            dst_order = sorted(dsts, key=lambda d: len(dst_paths.get(d, [])))

            for dst in dst_order:
                paths = dst_paths.get(dst, [])
                if not paths:
                    return None

                best_idx = 0
                best_total = float('inf')

                for idx, path in enumerate(paths):
                    test_edges = defaultdict(int, accumulated_edges)
                    test_out = defaultdict(set)
                    for k, v in accumulated_out.items():
                        test_out[k] = set(v)
                    test_in = defaultdict(set)
                    for k, v in accumulated_in.items():
                        test_in[k] = set(v)
                    test_nodes = set(accumulated_nodes)

                    for i in range(len(path)-1):
                        u, v = path[i], path[i+1]
                        test_edges[(u,v)] += num_partitions
                        test_out[u].add((u,v))
                        test_in[v].add((u,v))
                        test_nodes.add(u)
                        test_nodes.add(v)

                    eg_cost = 0.0
                    max_time = 0.0
                    for (u2,v2), cnt in test_edges.items():
                        c = G[u2][v2].get("cost", 0.0)
                        eg_cost += cnt * partition_size * c
                        edge_tp = G[u2][v2].get("throughput", 0.001)
                        n_out = len(test_out[u2])
                        n_in = len(test_in[v2])
                        eg_share = node_egress_bw(u2) / max(n_out, 1)
                        ig_share = node_ingress_bw(v2) / max(n_in, 1)
                        actual_bw = min(edge_tp, eg_share, ig_share)
                        if actual_bw <= 0:
                            actual_bw = 0.001
                        t = cnt * partition_size * 8.0 / actual_bw
                        if t > max_time:
                            max_time = t

                    ic = len(test_nodes) * num_vms * (instance_rate / 3600.0) * max_time
                    total = eg_cost + ic

                    if total < best_total:
                        best_total = total
                        best_idx = idx

                chosen = paths[best_idx]
                plan[dst] = [best_idx] * num_partitions
                for i in range(len(chosen)-1):
                    u, v = chosen[i], chosen[i+1]
                    accumulated_edges[(u,v)] += num_partitions
                    accumulated_out[u].add((u,v))
                    accumulated_in[v].add((u,v))
                    accumulated_nodes.add(u)
                    accumulated_nodes.add(v)

            return plan

        # Strategy 4: spread partitions across paths
        def strategy_spread():
            plan = {}
            for dst in dsts:
                paths = dst_paths.get(dst, [])
                if not paths:
                    return None
                if len(paths) == 1:
                    plan[dst] = [0] * num_partitions
                else:
                    # Try spreading across top 2-3 paths
                    n_spread = min(3, len(paths))
                    indices = []
                    for p in range(num_partitions):
                        indices.append(p % n_spread)
                    plan[dst] = indices
            return plan

        strategies = [
            strategy_cheapest,
            strategy_independent_best,
            strategy_greedy,
            strategy_spread,
        ]

        for strat_fn in strategies:
            try:
                plan = strat_fn()
                if plan is None:
                    continue
                c = compute_cost_for_plan(plan)
                if c < best_overall_cost:
                    best_overall_cost = c
                    best_overall_plan = dict(plan)
                    best_overall_vms = num_vms
            except:
                pass

    if best_overall_plan is None:
        # Fallback
        best_overall_plan = {}
        for dst in dsts:
            best_overall_plan[dst] = [0] * num_partitions
        best_overall_vms = 1

    num_vms = best_overall_vms

    # Local search: swap entire dst path
    improved = True
    rounds = 0
    while improved and rounds < 15:
        improved = False
        rounds += 1
        for dst in dsts:
            paths = dst_paths.get(dst, [])
            if not paths:
                continue
            cur_indices = best_overall_plan[dst]
            for new_idx in range(len(paths)):
                test = dict(best_overall_plan)
                test[dst] = [new_idx] * num_partitions
                tc = compute_cost_for_plan(test)
                if tc < best_overall_cost - 1e-12:
                    best_overall_cost = tc
                    best_overall_plan = test
                    improved = True

    # Local search: per-partition swaps
    improved = True
    rounds = 0
    while improved and rounds < 5:
        improved = False
        rounds += 1
        for dst in dsts:
            paths = dst_paths.get(dst, [])
            if not paths or len(paths) <= 1:
                continue
            for p in range(num_partitions):
                cur_idx = best_overall_plan[dst][p]
                for new_idx in range(len(paths)):
                    if new_idx == cur_idx:
                        continue
                    test = dict(best_overall_plan)
                    new_list = list(test[dst])
                    new_list[p] = new_idx
                    test[dst] = new_list
                    tc = compute_cost_for_plan(test)
                    if tc < best_overall_cost - 1e-12:
                        best_overall_cost = tc
                        best_overall_plan = test
                        improved = True

    # Simulated annealing
    random.seed(42)
    current = {d: list(v) for d, v in best_overall_plan.items()}
    current_cost = best_overall_cost
    sa_best = {d: list(v) for d, v in best_overall_plan.items()}
    sa_best_cost = best_overall_cost

    temp = max(best_overall_cost * 0.02, 0.5)
    cooling = 0.997

    n_iters = min(12000, len(dsts) * num_partitions * 40)

    for it in range(n_iters):
        dst = random.choice(dsts)
        paths = dst_paths.get(dst, [])
        if not paths or len(paths) <= 1:
            continue

        test = {d: list(v) for d, v in current.items()}

        if random.random() < 0.5:
            # Swap entire dst
            new_idx = random.randint(0, len(paths)-1)
            test[dst] = [new_idx] * num_partitions
        else:
            # Swap single partition
            p = random.randint(0, num_partitions - 1)
            new_idx = random.randint(0, len(paths)-1)
            test[dst][p] = new_idx

        tc = compute_cost_for_plan(test)
        delta = tc - current_cost
        if delta < 0 or (temp > 0 and random.random() < math.exp(-delta / max(temp, 1e-10))):
            current = test
            current_cost = tc
            if current_cost < sa_best_cost:
                sa_best_cost = current_cost
                sa_best = {d: list(v) for d, v in current.items()}
        temp *= cooling

    if sa_best_cost < best_overall_cost:
        best_overall_plan = sa_best
        best_overall_cost = sa_best_cost

    # Build topology
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    for dst in dsts:
        paths_list = dst_paths.get(dst, [])
        if not paths_list:
            continue
        indices = best_overall_plan.get(dst, [0] * num_partitions)
        for p in range(num_partitions):
            idx = indices[p] if p < len(indices) else 0
            if idx >= len(paths_list):
                idx = 0
            path = paths_list[idx]
            edges = make_edge_list(path)
            bc_topology.set_dst_partition_paths(dst, p, [edges])

    return bc_topology
'''
